/// <summary>
/// Task 414939: PB216 - Reduce Retry Limit
/// </summary>
[ExtensionOf(classStr(FormletterService))]
final class METFormletterService_Extension
{
    #define.METRetryLimit(2)

}

Method.Source:
/// <summary>
/// Change the retry limit from 5 to 2 for deadlock and update conflict exceptions.
/// </summary>
/// <param name = "_printout">A <c>PrintOut</c> value.</param>
/// <returns>true if the posting was successful; otherwise, false.</returns>
protected boolean processFormLetterParmTable(Printout _printout)
{
    try
    {
        return next processFormLetterParmTable(_printout);
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #METRetryLimit)
        {
            throw error(strFmt(
                "@MET:FormLetterRetryLimitReached",
                #METRetryLimit));
        }
        else
        {
            this.removeJournalFromList();
            formletterParmTable.reread();
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {                
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #METRetryLimit)
            {                    
                throw error(strFmt(
                    "@MET:FormLetterRetryLimitReached",
                    #METRetryLimit));                    
            }
            else
            {
                this.removeJournalFromList();
                formletterParmTable.reread();
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }        
}
